const d = $json;
const idEmpresa = String(d.id_empresa || '').trim();
const empresaValida = idEmpresa.length > 0;

return [{ json: {
  id_empresa: idEmpresa,
  empresa_valida: empresaValida,
  evento_resultado: empresaValida ? '' : 'ERRO_FOLLOWUP',
  erro: empresaValida ? '' : 'id_empresa é obrigatório e não pode ser vazio para executar o envio de follow-up (nunca fazer busca multi-tenant sem ID_EMPRESA).'
} }];

const ctx = $('CODE - Validar Empresa').first().json;

// Detecta falha técnica pelo campo error do item (nunca por contagem de itens:
// alwaysOutputData:true garante >=1 item mesmo em erro técnico - mesmo bug já
// confirmado e corrigido nos WF008/WF009/WF010/WF011).
const itensBusca = $items('GS - Buscar Empresa').map(i => i.json);
const itemComErro = itensBusca.find(r => r && r.error);
if (itemComErro) {
  const err = itemComErro.error || {};
  return [{ json: {
    ...ctx, pode_prosseguir: false, phone_number_id: '', timezone: 'America/Sao_Paulo',
    evento_resultado: 'ERRO_FOLLOWUP',
    erro: `Falha técnica ao consultar EMPRESAS no Google Sheets: ${String((err && err.message) || err || 'erro desconhecido')}`
  } }];
}

const rows = itensBusca.filter(r => r && r.ID_EMPRESA);

if (rows.length === 0) {
  return [{ json: {
    ...ctx, pode_prosseguir: false, phone_number_id: '', timezone: 'America/Sao_Paulo',
    evento_resultado: 'EMPRESA_NAO_ENCONTRADA',
    erro: 'Empresa não encontrada na aba EMPRESAS para o id_empresa informado.'
  } }];
}

const empresa = rows[0];
const phoneNumberId = String(empresa.WHATSAPP_PHONE_NUMBER_ID || '').trim();
// Fallback documentado: se TIMEZONE nao estiver cadastrado na empresa, usa America/Sao_Paulo
// (unico timezone real usado em todo o projeto ate o momento) em vez de bloquear a execucao.
const timezone = String(empresa.TIMEZONE || '').trim() || 'America/Sao_Paulo';

if (!phoneNumberId) {
  return [{ json: {
    ...ctx, pode_prosseguir: false, phone_number_id: '', timezone,
    evento_resultado: 'WHATSAPP_NAO_CONFIGURADO',
    erro: 'WHATSAPP_PHONE_NUMBER_ID não está configurado para esta empresa em EMPRESAS.'
  } }];
}

const agoraIso = DateTime.now().setZone(timezone).toISO();

return [{ json: {
  ...ctx, pode_prosseguir: true, phone_number_id: phoneNumberId, timezone, agora_iso: agoraIso, evento_resultado: ''
} }];

const ctx = $('CODE - Avaliar Empresa WhatsApp').first().json;
const idEmpresa = ctx.id_empresa;
const phoneNumberId = ctx.phone_number_id || '';
const timezone = ctx.timezone || 'America/Sao_Paulo';

const cliRaw = $items('GS - Buscar Clientes').map(i => i.json);
const agRaw = $items('GS - Buscar Agendamentos').map(i => i.json);
const foRaw = $items('GS - Buscar Followups Existentes').map(i => i.json);

// Detecta falha técnica explicitamente pelo campo error de cada item (nunca por
// contagem de itens: alwaysOutputData:true garante >=1 item mesmo em falha técnica,
// então "0 itens" nunca é um sinal confiável - mesmo bug já confirmado e corrigido nos
// WF008/09/10/11).
const erroCli = cliRaw.find(r => r && r.error);
const erroAg = agRaw.find(r => r && r.error);
const erroFo = foRaw.find(r => r && r.error);
const itemComErro = erroCli || erroAg || erroFo;

if (itemComErro) {
  const origemErro = erroCli ? 'CLIENTES' : (erroAg ? 'AGENDAMENTOS' : 'FOLLOWUPS');
  const err = itemComErro.error || {};
  return [{ json: {
    id_empresa: idEmpresa, id_cliente: '', id_followup: '', tentativa: 0, ultimo_atendimento: '',
    telefone_cliente: '', nome_cliente: '', phone_number_id: phoneNumberId, precisa_enviar: false, enviado: false,
    origem: 'AUTOMATICO',
    evento_resultado: 'ERRO_FOLLOWUP',
    erro: `Falha técnica ao consultar ${origemErro} no Google Sheets: ${String((err && err.message) || err || 'erro desconhecido')}`
  } }];
}

const clientes = cliRaw.filter(r => r && r.ID_CLIENTE);
const agendamentos = agRaw.filter(r => r && r.ID_AGENDAMENTO);
const followups = foRaw.filter(r => r && r.ID_FOLLOWUP);

const agora = ctx.agora_iso ? DateTime.fromISO(ctx.agora_iso, { zone: timezone }) : DateTime.now().setZone(timezone);

function parseDataHora(dataStr, horaStr) {
  const hora = String(horaStr || '00:00').slice(0, 5);
  let dt = DateTime.fromFormat(`${dataStr} ${hora}`, 'dd/MM/yyyy HH:mm', { zone: timezone });
  if (!dt.isValid) dt = DateTime.fromFormat(`${dataStr} ${hora}`, 'yyyy-MM-dd HH:mm', { zone: timezone });
  if (!dt.isValid) dt = DateTime.fromISO(`${dataStr}T${hora}`, { zone: timezone });
  return dt;
}

// Janelas de detecção (decisão técnica conservadora, documentada no relatório: o projeto
// não define tolerância de execução periódica). Alvos aprovados: 30 e 45 dias após o
// último atendimento real. Usamos uma folga de +3 dias em cada janela para tolerar
// execuções não perfeitamente pontuais, sem sobrepor as duas janelas entre si.
const TENTATIVA1_MIN_DIAS = 30, TENTATIVA1_MAX_DIAS = 33;
const TENTATIVA2_MIN_DIAS = 45, TENTATIVA2_MAX_DIAS = 48;

if (clientes.length === 0) {
  return [{ json: {
    id_empresa: idEmpresa, id_cliente: '', id_followup: '', tentativa: 0, ultimo_atendimento: '',
    telefone_cliente: '', nome_cliente: '', precisa_enviar: false, enviado: false,
    evento_resultado: 'CLIENTE_NAO_ELEGIVEL',
    erro: 'Nenhum cliente ATIVO com ACEITA_MARKETING=SIM encontrado para esta empresa.'
  } }];
}

const candidatos = [];

for (const cli of clientes) {
  const agsCliente = agendamentos.filter(a => String(a.ID_CLIENTE) === String(cli.ID_CLIENTE));

  const passados = [];
  const futuros = [];
  for (const a of agsCliente) {
    // Nunca considerar CANCELADO nem como atendimento realizado, nem como agendamento futuro.
    if (String(a.STATUS || '').toUpperCase() === 'CANCELADO') continue;

    const fim = parseDataHora(a.DATA, a.HORA_FIM);
    if (fim.isValid && fim <= agora) {
      passados.push({ ag: a, fim });
      continue;
    }
    const inicio = parseDataHora(a.DATA, a.HORA_INICIO);
    if (inicio.isValid && inicio > agora) {
      futuros.push(a);
    }
  }

  const base = {
    id_empresa: idEmpresa,
    id_cliente: cli.ID_CLIENTE,
    telefone_cliente: String(cli.TELEFONE || '').replace(/\D/g, ''),
    nome_cliente: cli.NOME || '',
    phone_number_id: phoneNumberId
  };

  if (!base.telefone_cliente) {
    candidatos.push({ ...base, precisa_enviar: false, enviado: false, tentativa: 0, ultimo_atendimento: '', evento_resultado: 'CLIENTE_NAO_ELEGIVEL', erro: 'Cliente sem telefone válido cadastrado.' });
    continue;
  }

  if (futuros.length > 0) {
    candidatos.push({ ...base, precisa_enviar: false, enviado: false, tentativa: 0, ultimo_atendimento: '', evento_resultado: 'CLIENTE_COM_AGENDAMENTO_FUTURO', erro: 'Cliente já possui agendamento futuro; não enviar follow-up.' });
    continue;
  }

  if (passados.length === 0) {
    // Cliente nunca teve atendimento real registrado: não é "inativo", apenas não se aplica ainda.
    continue;
  }

  passados.sort((a, b) => b.fim.toMillis() - a.fim.toMillis());
  const ultimoAtendimento = passados[0];
  const ultimoAtendimentoStr = ultimoAtendimento.ag.DATA;
  const diasDesde = agora.diff(ultimoAtendimento.fim, 'days').days;

  let tentativaElegivel = 0;
  if (diasDesde >= TENTATIVA2_MIN_DIAS && diasDesde <= TENTATIVA2_MAX_DIAS) tentativaElegivel = 2;
  else if (diasDesde >= TENTATIVA1_MIN_DIAS && diasDesde <= TENTATIVA1_MAX_DIAS) tentativaElegivel = 1;

  if (tentativaElegivel === 0) {
    // Fora das janelas de 30/45 dias nesta execução (cedo demais, entre janelas, ou tarde demais).
    continue;
  }

  // Idempotência: ID_EMPRESA + ID_CLIENTE + ULTIMO_ATENDIMENTO (identifica o ciclo de inatividade) + TENTATIVA.
  // Um novo atendimento real muda ULTIMO_ATENDIMENTO, o que automaticamente inicia um novo ciclo elegível.
  const jaEnviado = followups.some(f =>
    String(f.ID_CLIENTE) === String(cli.ID_CLIENTE) &&
    String(f.ULTIMO_ATENDIMENTO) === String(ultimoAtendimentoStr) &&
    Number(f.TENTATIVA) === tentativaElegivel &&
    String(f.STATUS || '').toUpperCase() === 'ENVIADO'
  );

  if (jaEnviado) {
    candidatos.push({ ...base, precisa_enviar: false, enviado: false, tentativa: tentativaElegivel, ultimo_atendimento: ultimoAtendimentoStr, evento_resultado: 'FOLLOWUP_JA_ENVIADO', erro: `Tentativa ${tentativaElegivel} já enviada com sucesso para este ciclo de inatividade.` });
    continue;
  }

  const nomeExibicao = base.nome_cliente && base.nome_cliente.trim() ? base.nome_cliente.trim() : 'Cliente';
  const mensagem = `Oi, ${nomeExibicao}! 😊 Faz um tempinho desde o seu último atendimento com a gente. Se quiser agendar novamente, posso te ajudar a encontrar um horário disponível.`;

  candidatos.push({
    ...base,
    precisa_enviar: true,
    enviado: false,
    tentativa: tentativaElegivel,
    ultimo_atendimento: ultimoAtendimentoStr,
    resposta_cliente: mensagem,
    origem: 'AUTOMATICO'
  });
}

if (candidatos.length === 0) {
  return [{ json: {
    id_empresa: idEmpresa, id_cliente: '', id_followup: '', tentativa: 0, ultimo_atendimento: '',
    telefone_cliente: '', nome_cliente: '', precisa_enviar: false, enviado: false,
    evento_resultado: 'CLIENTE_NAO_ELEGIVEL',
    erro: 'Nenhum cliente dentro das janelas de follow-up (30 ou 45 dias) nesta execução.'
  } }];
}

return candidatos.map(c => ({ json: c }));

const envio = $json; // resposta de EXEC - WF012 Comunicação para ESTE follow-up especificamente

// Roda em modo "Run Once for Each Item" propositalmente (mesma correção já validada no
// WF011): no modo padrão, $json equivaleria sempre ao primeiro item e este node só
// devolveria 1 resultado mesmo recebendo vários follow-ups elegíveis na mesma execução -
// os demais seriam descartados silenciosamente.
//
// NÃO usar $('CODE - Avaliar Follow-ups Elegíveis').item.json aqui: essa referência
// atravessa o limite do EXEC - WF012 Comunicação (Execute Workflow) e já quebrou em
// teste real ("Cannot read properties of undefined (reading 'error')"). A correção é
// usar somente os campos que o próprio WF012 já ecoa de volta em $json
// (id_empresa/id_cliente/telefone_cliente/nome_cliente/phone_number_id/
// resposta_cliente/origem) e o pacote dados, que WF015 já envia como Object com
// tipo/tentativa/ultimo_atendimento.
const dados = envio.dados && typeof envio.dados === 'object' ? envio.dados : {};

const followup = {
  id_empresa: envio.id_empresa || '',
  id_cliente: envio.id_cliente || '',
  telefone_cliente: String(envio.telefone_cliente || '').replace(/\D/g, ''),
  nome_cliente: envio.nome_cliente || '',
  phone_number_id: envio.phone_number_id || '',
  tentativa: Number(dados.tentativa ?? envio.tentativa ?? 0),
  ultimo_atendimento: dados.ultimo_atendimento || envio.ultimo_atendimento || '',
  resposta_cliente: envio.resposta_cliente || envio.mensagem_final || '',
  origem: envio.origem || 'AUTOMATICO'
};

const enviado = envio.enviado === true;

// .first() é seguro aqui: contexto da empresa é global/singleton na execução (1 busca de
// empresa por execução, nunca por cliente), não dado por item.
const timezone = $('CODE - Avaliar Empresa WhatsApp').first().json.timezone || 'America/Sao_Paulo';
const agora = DateTime.now().setZone(timezone).toISO();
const idFollowup = `FUP${Date.now()}${Math.random().toString(36).slice(2, 8)}`;

let erroTexto = '';
if (typeof envio.erro === 'string') {
  erroTexto = envio.erro;
} else if (envio.erro && typeof envio.erro === 'object') {
  erroTexto = envio.erro.message || JSON.stringify(envio.erro);
}

return { json: {
  ...followup,
  ID_FOLLOWUP: idFollowup,
  ID_EMPRESA: followup.id_empresa,
  ID_CLIENTE: followup.id_cliente,
  TELEFONE: followup.telefone_cliente,
  ULTIMO_ATENDIMENTO: followup.ultimo_atendimento,
  TENTATIVA: followup.tentativa,
  STATUS: enviado ? 'ENVIADO' : 'FALHA',
  DATA_HORA: agora,
  WHATSAPP_MESSAGE_ID: envio.whatsapp_message_id || '',
  OBSERVACOES: enviado ? '' : erroTexto,
  id_followup: idFollowup,
  enviado: enviado,
  evento_resultado: enviado ? 'FOLLOWUP_ENVIADO' : 'ERRO_FOLLOWUP',
  erro: enviado ? '' : erroTexto
} };

// Modo "Run Once for All Items" (voltou ao padrão - ver por quê abaixo). Este node é
// alimentado pela saída de ERRO de GS - Registrar Followup, que pode ser:
// (a) uma falha GLOBAL/estrutural (ex.: aba inexistente) - confirmado em teste real: o
//     Google Sheets recebeu N itens mas devolveu só 1 item de erro, SEM nenhuma
//     informação de pairedItem (n8n lançou "Paired item data ... is unavailable" ao
//     tentar itemMatching contra ele); ou
// (b) falhas por linha (se o Google Sheets algum dia produzir isso de fato).
// Por isso NUNCA tentamos correlacionar um item de erro a um follow-up original via
// pairedItem/itemMatching/.item/.first() - reconstruímos por diferença: todo follow-up
// original que NÃO aparece nos itens realmente gravados com sucesso (branch 0 de
// GS - Registrar Followup) é considerado falho. Isso cobre tanto a falha global (0
// sucessos -> todos os originais falharam) quanto uma eventual falha parcial (alguns
// sucessos -> só os que não estão lá falharam), sem depender de nenhuma correlação
// posicional ou de pairedItem entre o(s) item(ns) de erro e os originais.
const originais = $('CODE - Processar Resultado Envio').all().map(i => i.json);

let sucessos = [];
try {
  // branch 0 = saída de sucesso de GS - Registrar Followup (o que foi realmente gravado).
  sucessos = $('GS - Registrar Followup').all(0, $runIndex).map(i => i.json);
} catch (e) {
  sucessos = [];
}
const idsComSucesso = new Set(sucessos.map(s => s.ID_FOLLOWUP).filter(Boolean));

const falharam = originais.filter(o => !idsComSucesso.has(o.id_followup));

// Mensagem de erro: com 1 único item de erro (caso confirmado em teste real - falha
// global), usa essa mensagem para todos os originais que falharam. Com mais de um item de
// erro (falha por linha, não observada neste projeto mas coberta defensivamente), junta as
// mensagens distintas - nunca tenta adivinhar qual mensagem pertence a qual item original.
const itensErro = items.map(i => i.json);
const mensagensErro = [...new Set(itensErro.map(i => {
  const err = i.error || {};
  return String((err && err.message) || err || 'erro desconhecido');
}))];
const mensagemErro = mensagensErro.join(' | ') || 'Falha técnica ao gravar em FOLLOWUPS.';

return falharam.map(f => ({ json: {
  id_empresa: f.id_empresa,
  id_cliente: f.id_cliente,
  id_followup: f.id_followup,
  tentativa: f.tentativa,
  ultimo_atendimento: f.ultimo_atendimento,
  enviado: f.enviado,
  resposta_cliente: f.resposta_cliente,
  origem: f.origem,
  evento_resultado: 'ERRO_FOLLOWUP',
  erro: `Follow-up processado (enviado=${f.enviado}) mas falhou ao registrar em FOLLOWUPS: ${mensagemErro}`
} }));
